class Solution
{
public:
    bool verifyPreorder(vector< int>& preorder)
    {
        stack< int>st;
        long long lower = LLONG_MIN;
        for (int x : preorder)
        {
            if (x <= lower)
            {
                return false;
            }
            while (!st.empty() && x >st.top())
            {
                lower = st.top();
                st.pop();
            }
            st.push(x);
        }
        return true;
    }
};
